def resolve_permissions(role: str, parents: dict[str,str], grants: dict[str,list[str]]) -> list[str] | None:
    seen=set(); out=set()
    while role:
        if role not in parents and role not in grants or role in seen: return None
        seen.add(role); out.update(grants.get(role,[])); role=parents.get(role,'')
    return sorted(out)
